DROP TABLE IF EXISTS `agent_assignment`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `agent_assignment` (
  `assignment_id` int NOT NULL AUTO_INCREMENT COMMENT 'Mã phân công làm việc',
  `listing_id` int NOT NULL COMMENT 'Mã tin đăng được phân công (Khóa ngoại)',
  `agent_id` int NOT NULL COMMENT 'Mã môi giới đảm nhận (Khóa ngoại)',
  `assignment_role` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'LEAD' COMMENT 'Vai trò phụ trách (LEAD: Trưởng nhóm, SUPPORT: Hỗ trợ)',
  `assigned_from` datetime NOT NULL COMMENT 'Thời điểm bắt đầu phân công',
  `assigned_to` datetime DEFAULT NULL COMMENT 'Thời điểm kết thúc phân công (NULL nếu đang đảm nhận)',
  PRIMARY KEY (`assignment_id`),
  KEY `fk_assign_listing` (`listing_id`),
  KEY `fk_assign_agent` (`agent_id`),
  CONSTRAINT `fk_assign_agent` FOREIGN KEY (`agent_id`) REFERENCES `agent` (`agent_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_assign_listing` FOREIGN KEY (`listing_id`) REFERENCES `listing` (`listing_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_assign_role` CHECK ((`assignment_role` in (_utf8mb4'LEAD',_utf8mb4'SUPPORT')))
) ENGINE=InnoDB AUTO_INCREMENT=12205 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Bảng ghi nhận phân công trách nhiệm môi giới theo tin đăng';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `agent_assignment`
--

LOCK TABLES `agent_assignment` WRITE;
/*!40000 ALTER TABLE `agent_assignment` DISABLE KEYS */;
