--
-- Table structure for table `financial_entry`
--

DROP TABLE IF EXISTS `financial_entry`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `financial_entry` (
  `entry_id` int NOT NULL AUTO_INCREMENT COMMENT 'Mã bút toán tài chính duy nhất',
  `property_id` int NOT NULL COMMENT 'Mã bất động sản phát sinh tài chính (Khóa ngoại)',
  `listing_id` int DEFAULT NULL COMMENT 'Mã tin đăng tham chiếu (Khóa ngoại tùy chọn)',
  `lease_id` int DEFAULT NULL COMMENT 'Mã hợp đồng thuê tham chiếu (Khóa ngoại tùy chọn)',
  `maintenance_id` int DEFAULT NULL COMMENT 'Mã yêu cầu bảo trì tham chiếu (Khóa ngoại tùy chọn)',
  `entry_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Loại hình (RENT, DEPOSIT, REPAIR_FEE, COMMISSION)',
  `direction` varchar(5) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Chiều dòng tiền (IN: Thu vào / CREDIT, OUT: Chi ra / DEBIT)',
  `amount` decimal(15,2) NOT NULL COMMENT 'Số tiền giao dịch (luôn dương)',
  `currency` varchar(3) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'VND' COMMENT 'Mã tiền tệ ISO 4217 (VND, USD, EUR)',
  `occurred_at` datetime NOT NULL COMMENT 'Thời điểm phát sinh thực tế theo chứng từ',
  `posted_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Thời điểm ghi nhận vào sổ cái hệ thống',
  `reversal_of_entry_id` int DEFAULT NULL COMMENT 'Self-reference FK: Mã bút toán gốc bị đảo/sửa sai (nếu có)',
  PRIMARY KEY (`entry_id`),
  KEY `fk_fe_reversal` (`reversal_of_entry_id`),
  KEY `idx_fe_property_ledger` (`property_id`,`posted_at`),
  KEY `fk_fe_listing` (`listing_id`),
  KEY `fk_fe_lease` (`lease_id`),
  KEY `fk_fe_maint` (`maintenance_id`),
  CONSTRAINT `fk_fe_lease` FOREIGN KEY (`lease_id`) REFERENCES `lease` (`lease_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_fe_listing` FOREIGN KEY (`listing_id`) REFERENCES `listing` (`listing_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_fe_maint` FOREIGN KEY (`maintenance_id`) REFERENCES `maintenance_request` (`maintenance_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_fe_property` FOREIGN KEY (`property_id`) REFERENCES `property` (`property_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_fe_reversal` FOREIGN KEY (`reversal_of_entry_id`) REFERENCES `financial_entry` (`entry_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_fe_amount` CHECK ((`amount` > 0)),
  CONSTRAINT `chk_fe_direction` CHECK ((`direction` in (_utf8mb4'IN',_utf8mb4'OUT')))
) ENGINE=InnoDB AUTO_INCREMENT=8469 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Sổ cái tài chính bất biến (Append-Only Financial Ledger)';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `financial_entry`
--

