--
-- Table structure for table `listing`
--

DROP TABLE IF EXISTS `listing`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `listing` (
  `listing_id` int NOT NULL AUTO_INCREMENT COMMENT 'Mã định danh duy nhất của tin đăng',
  `property_id` int NOT NULL COMMENT 'Mã bất động sản được chào (Khóa ngoại)',
  `listing_type` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Loại tin đăng (SALE: Bán, RENT: Cho thuê)',
  `offer_amount` decimal(15,2) NOT NULL COMMENT 'Giá chào bán hoặc tiền thuê định kỳ đề xuất',
  `start_date` date NOT NULL COMMENT 'Ngày bắt đầu công bố tin đăng',
  `end_date` date DEFAULT NULL COMMENT 'Ngày đóng tin đăng',
  `listing_status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE' COMMENT 'Trạng thái tin đăng (ACTIVE, CLOSED, CANCELLED, PAUSED)',
  PRIMARY KEY (`listing_id`),
  KEY `idx_listing_active` (`property_id`,`listing_status`),
  CONSTRAINT `fk_listing_property` FOREIGN KEY (`property_id`) REFERENCES `property` (`property_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_listing_offer` CHECK ((`offer_amount` > 0)),
  CONSTRAINT `chk_listing_status` CHECK ((`listing_status` in (_utf8mb4'ACTIVE',_utf8mb4'CLOSED',_utf8mb4'CANCELLED',_utf8mb4'PAUSED'))),
  CONSTRAINT `chk_listing_type` CHECK ((`listing_type` in (_utf8mb4'SALE',_utf8mb4'RENT')))
) ENGINE=InnoDB AUTO_INCREMENT=10001 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Bảng danh sách các tin đăng chào bán hoặc cho thuê';
/*!40101 SET character_set_client = @saved_cs_client */;

