--
-- Table structure for table `maintenance_request`
--

DROP TABLE IF EXISTS `maintenance_request`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `maintenance_request` (
  `maintenance_id` int NOT NULL AUTO_INCREMENT COMMENT 'Mã định danh yêu cầu bảo trì',
  `property_id` int NOT NULL COMMENT 'Mã bất động sản phát sinh sự cố (Khóa ngoại)',
  `reporter_tenant_id` int DEFAULT NULL COMMENT 'Mã người thuê gửi báo cáo (Khóa ngoại, tùy chọn)',
  `priority` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MEDIUM' COMMENT 'Mức độ ưu tiên (LOW, MEDIUM, HIGH, URGENT)',
  `blocking_flag` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'TRUE: Cản trở sinh hoạt (đổi trạng thái BĐS sang UNDER_MAINTENANCE)',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'OPEN' COMMENT 'Trạng thái (OPEN, ASSIGNED, IN_PROGRESS, COMPLETED, CANCELLED)',
  `opened_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Thời điểm tiếp nhận yêu cầu',
  `closed_at` datetime DEFAULT NULL COMMENT 'Thời điểm nghiệm thu hoàn thành hoặc hủy',
  PRIMARY KEY (`maintenance_id`),
  KEY `fk_maint_property` (`property_id`),
  KEY `fk_maint_tenant` (`reporter_tenant_id`),
  CONSTRAINT `fk_maint_property` FOREIGN KEY (`property_id`) REFERENCES `property` (`property_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_maint_tenant` FOREIGN KEY (`reporter_tenant_id`) REFERENCES `tenant` (`tenant_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `chk_maint_priority` CHECK ((`priority` in (_utf8mb4'LOW',_utf8mb4'MEDIUM',_utf8mb4'HIGH',_utf8mb4'URGENT'))),
  CONSTRAINT `chk_maint_status` CHECK ((`status` in (_utf8mb4'OPEN',_utf8mb4'ASSIGNED',_utf8mb4'IN_PROGRESS',_utf8mb4'COMPLETED',_utf8mb4'CANCELLED')))
) ENGINE=InnoDB AUTO_INCREMENT=1501 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Bảng quản lý yêu cầu bảo trì và sự cố tài sản';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `maintenance_request`
--

LOCK TABLES `maintenance_request` WRITE;
/*!40000 ALTER TABLE `maintenance_request` DISABLE KEYS */;
