CREATE TABLE `owner` (
  `owner_id` int NOT NULL AUTO_INCREMENT COMMENT 'Mã định danh duy nhất của chủ sở hữu',
  `full_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Họ và tên đầy đủ của chủ sở hữu',
  `email` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Địa chỉ email duy nhất dùng để liên hệ',
  `phone` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Số điện thoại liên lạc',
  PRIMARY KEY (`owner_id`),
  UNIQUE KEY `email` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=3501 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Bảng thông tin chủ sở hữu bất động sản';
