--
-- Table structure for table `property`
--

DROP TABLE IF EXISTS `property`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `property` (
  `property_id` int NOT NULL AUTO_INCREMENT COMMENT 'Mã định danh duy nhất của bất động sản',
  `address` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Địa chỉ chuẩn hóa (Số nhà, đường, phường/xã, quận/huyện)',
  `unit` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Mã căn hộ hoặc số phòng (VD: A-1204)',
  `property_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Loại hình BĐS (Căn hộ, Nhà phố, Biệt thự, Mặt bằng)',
  `area` decimal(10,2) NOT NULL COMMENT 'Diện tích tính bằng mét vuông (m²)',
  `bedrooms` int NOT NULL DEFAULT '0' COMMENT 'Số lượng phòng ngủ',
  `current_status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'AVAILABLE' COMMENT 'Trạng thái hiện tại (AVAILABLE, LEASED, UNDER_MAINTENANCE)',
  PRIMARY KEY (`property_id`),
  KEY `idx_property_status` (`current_status`),
  CONSTRAINT `chk_property_area` CHECK ((`area` > 0)),
  CONSTRAINT `chk_property_bedrooms` CHECK ((`bedrooms` >= 0)),
  CONSTRAINT `chk_property_status` CHECK ((`current_status` in (_utf8mb4'AVAILABLE',_utf8mb4'LEASED',_utf8mb4'UNDER_MAINTENANCE')))
) ENGINE=InnoDB AUTO_INCREMENT=10001 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Bảng quản lý thông tin tài sản bất động sản';
/*!40101 SET character_set_client = @saved_cs_client */;

