--
-- Table structure for table `property_status_history`
--

DROP TABLE IF EXISTS `property_status_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `property_status_history` (
  `status_history_id` int NOT NULL AUTO_INCREMENT COMMENT 'Mã lịch sử trạng thái',
  `property_id` int NOT NULL COMMENT 'Mã bất động sản (Khóa ngoại)',
  `status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Trạng thái ghi nhận (AVAILABLE, LEASED, UNDER_MAINTENANCE)',
  `valid_from` datetime NOT NULL COMMENT 'Thời điểm bắt đầu hiệu lực trạng thái',
  `valid_to` datetime DEFAULT NULL COMMENT 'Thời điểm kết thúc (NULL đại diện cho trạng thái hiện hành)',
  `reason` text COLLATE utf8mb4_unicode_ci COMMENT 'Lý do diễn giải thay đổi trạng thái',
  PRIMARY KEY (`status_history_id`),
  KEY `idx_psh_current` (`property_id`,`valid_to`),
  CONSTRAINT `fk_psh_property` FOREIGN KEY (`property_id`) REFERENCES `property` (`property_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_psh_status` CHECK ((`status` in (_utf8mb4'AVAILABLE',_utf8mb4'LEASED',_utf8mb4'UNDER_MAINTENANCE')))
) ENGINE=InnoDB AUTO_INCREMENT=13593 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Sổ cái lịch sử trạng thái vận hành bất động sản';
/*!40101 SET character_set_client = @saved_cs_client */;

